        {"id": "e6-2-pee-7", "title": "Train en retard", "situation": "", "sourceMessage": {"from": "Mounir", "subject": "Je t'attends", "body": "Salut,\nJe suis à la gare. Est-ce que ton train arrive bientôt ?\nMounir"}, "instruction": "Répondez à Mounir pour annoncer le retard du train, vous excuser et donner la nouvelle heure d'arrivée.", "points": []},
