for _pool_name, _pool in (("PE_MESSAGE", PE_MESSAGE), ("PE_EMAIL", PE_EMAIL)):
    for _key in EXPECTED_KEYS:
        assert len(_pool[_key]) == 20, f"{_pool_name}[{_key}] must contain 20 prompts"
        for _prompt in _pool[_key]:
            assert _prompt["points"] == [], f"{_prompt['id']} points must be empty"
            assert "\n" not in _prompt["instruction"], f"{_prompt['id']} instruction must be continuous prose"
            _text = " ".join(
                str(_prompt.get(_field, ""))
                for _field in ("id", "title", "situation", "instruction")
            )
            if "sourceMessage" in _prompt:
                _source = _prompt["sourceMessage"]
                _text += " " + " ".join(
                    str(_source.get(_field, ""))
                    for _field in ("from", "subject", "body")
                )
            assert FORBIDDEN_VARIANT_WORD not in _text.lower(), f"{_prompt['id']} must not mention the forbidden variant marker"
